bounded_host_request.command:
set -euo pipefail
net=deploy_default
test "$(docker network inspect -f '{{.Internal}}' "$net")" = false || exit 80
docker image inspect create-videobot:local-poll >/dev/null 2>&1 || exit 61
docker run --rm --network "$net" --pull never --read-only --cap-drop ALL --security-opt no-new-privileges:true --entrypoint node create-videobot:local-poll --input-type=module -e '
import {setDefaultResultOrder} from "node:dns";
setDefaultResultOrder("ipv4first");
try{
 const r=await fetch("https://api.telegram.org",{signal:AbortSignal.timeout(10000)});
 if(r.status>=200 && r.status<500)process.exitCode=0;
 else process.exitCode=82;
}catch(e){
 const cause=String(e?.cause?.code??e?.code??"");
 process.exitCode= cause==="ENETUNREACH"?83:cause==="ENOTFOUND"?84:cause==="ETIMEDOUT"?85:cause==="ECONNREFUSED"?86:87;
}'
